begin;
select plan(15);
select ok(not (select prosecdef from pg_proc where oid='public.community_page(text,text,text,boolean,timestamptz,uuid,integer,uuid)'::regprocedure),'Feed runs with caller RLS');
select ok(not (select prosecdef from pg_proc where oid='public.community_author(text)'::regprocedure),'Author counts use caller RLS');
select ok(not (select prosecdef from pg_proc where oid='public.community_categories()'::regprocedure),'Categories use caller RLS');
select ok(not has_function_privilege('anon','public.community_page(text,text,text,boolean,timestamptz,uuid,integer,uuid)','EXECUTE'),'No anonymous feed');
select ok(not has_function_privilege('anon','public.community_author(text)','EXECUTE'),'No anonymous social profile');
select ok(not has_function_privilege('anon','public.community_categories()','EXECUTE'),'No anonymous categories');
select ok(not has_function_privilege('anon','public.create_comment_once(uuid,uuid,text)','EXECUTE'),'No anonymous comment creation');
select ok(has_function_privilege('authenticated','public.community_page(text,text,text,boolean,timestamptz,uuid,integer,uuid)','EXECUTE'),'Authenticated projection callable');
select ok(not (select prosecdef from pg_proc where oid='public.create_comment_once(uuid,uuid,text)'::regprocedure),'Comment public wrapper invoker');
select ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='private.create_comment_once(uuid,uuid,text)'::regprocedure),'Comment implementation closes search path');
select ok(exists(select 1 from pg_indexes where indexname='recipes_public_chronological'),'Published timestamp and UUID descending index');
select ok(exists(select 1 from pg_trigger where tgrelid='public.recipe_comments'::regclass and tgname='creation_limit'),'Historical comment quotas preserved');
select ok((select relrowsecurity from pg_class where oid='private.comment_creation_requests'::regclass),'Comment ledger uses RLS');
select ok(not has_table_privilege('authenticated','private.comment_creation_requests','SELECT'),'Comment ledger not exposed to clients');
select ok(exists(select 1 from pg_constraint where conrelid='public.recipe_comments'::regclass and conname='comment_non_whitespace'),'Whitespace-only comments rejected by DB');
select * from finish();
rollback;
